// Parse robots.txt into a per-bot verdict.
const cfg = $('Set Audit Parameters').first().json;
const robotsTxt = String($json.data || $json.body || '');
const httpStatus = $json.__status;

const BOTS = cfg.bots;
// `new URL()` is not available in the Code node sandbox, so derive the path by hand.
const afterScheme = String(cfg.testUrl).replace(/^https?:\/\//, '');
const slash = afterScheme.indexOf('/');
const testPath = slash === -1 ? '/' : (afterScheme.slice(slash).split('#')[0].split('?')[0] || '/');

// Build user-agent blocks. A group can declare several user-agents before its rules.
const groups = [];
let current = null;
let lastWasUserAgent = false;

for (const rawLine of robotsTxt.split('\n')) {
  const line = rawLine.replace(/#.*$/, '').trim();
  if (!line) continue;
  const sep = line.indexOf(':');
  if (sep === -1) continue;
  const field = line.slice(0, sep).trim().toLowerCase();
  const value = line.slice(sep + 1).trim();

  if (field === 'user-agent') {
    if (!lastWasUserAgent || !current) {
      current = { agents: [], rules: [] };
      groups.push(current);
    }
    current.agents.push(value.toLowerCase());
    lastWasUserAgent = true;
  } else if ((field === 'allow' || field === 'disallow') && current) {
    current.rules.push({ type: field, path: value });
    lastWasUserAgent = false;
  } else {
    lastWasUserAgent = false;
  }
}

// Longest-match wins, Allow beats Disallow on equal length (robots.txt standard).
function matches(pattern, path) {
  if (pattern === '') return false;
  let regex = '';
  for (const ch of pattern) {
    if (ch === '*') regex += '.*';
    else if (ch === '$') regex += '$';
    else regex += ch.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp('^' + regex).test(path);
}

function verdictFor(botName) {
  const bot = botName.toLowerCase();
  let group = groups.find(g => g.agents.includes(bot));
  let matchedBy = 'own rules';
  if (!group) {
    group = groups.find(g => g.agents.includes('*'));
    matchedBy = 'the wildcard User-agent: * group';
  }
  if (!group) {
    return { robots: 'ALLOWED', robotsDetail: 'no matching group in robots.txt, so nothing restricts this bot' };
  }

  let best = null;
  for (const rule of group.rules) {
    if (rule.type === 'disallow' && rule.path === '') continue; // empty Disallow means allow all
    if (!matches(rule.path, testPath)) continue;
    if (!best || rule.path.length > best.path.length ||
        (rule.path.length === best.path.length && rule.type === 'allow')) {
      best = rule;
    }
  }

  if (!best) {
    return { robots: 'ALLOWED', robotsDetail: `no rule in ${matchedBy} matches ${testPath}` };
  }
  const blocked = best.type === 'disallow';
  return {
    robots: blocked ? 'BLOCKED' : 'ALLOWED',
    robotsDetail: `${best.type === 'allow' ? 'Allow' : 'Disallow'}: ${best.path} (from ${matchedBy})`,
  };
}

const robotsAbsent = httpStatus === 404 || (httpStatus === 200 && robotsTxt.trim() === '');
const robotsUnreadable = httpStatus !== 200 && httpStatus !== 404;

return BOTS.map(bot => ({
  json: {
    bot: bot.name,
    userAgent: bot.ua,
    purpose: bot.purpose,
    testUrl: cfg.testUrl,
    secondsBetweenRequests: cfg.secondsBetweenRequests,
    robotsStatus: httpStatus,
    ...(robotsAbsent
      ? { robots: 'ALLOWED', robotsDetail: 'no robots.txt on this domain, so every bot is allowed by default' }
      : robotsUnreadable
        ? { robots: 'UNKNOWN', robotsDetail: `robots.txt could not be read (HTTP ${httpStatus}), so its rules are unknown` }
        : verdictFor(bot.name)),
  },
}));

// Keep the bot metadata next to the response, and add a browser control run at the end.
const bots = $('Resolve robots.txt Rules').all();
const responses = $input.all();
const out = responses.map((r, i) => ({
  json: {
    ...bots[i].json,
    __status: r.json.statusCode,
    __length: String(r.json.data || '').length,
  },
}));
const cfg = $('Set Audit Parameters').first().json;
out.push({ json: { bot: '__control__', userAgent: cfg.browserUserAgent, testUrl: cfg.testUrl, secondsBetweenRequests: cfg.secondsBetweenRequests } });
return out;

// Compare what robots.txt promises with what the server actually does.
const items = $input.all();

// The browser control run is the last item; everything before it is a bot.
const control = items.find(i => i.json.bot === '__control__');
const controlLength = control ? Number(control.json.__length || 0) : 0;
const controlStatus = control ? Number(control.json.__status || 0) : 0;

const results = [];

for (const item of items) {
  const d = item.json;
  if (d.bot === '__control__') continue;

  const status = Number(d.__status || 0);
  const length = Number(d.__length || 0);
  const robotsAllowed = d.robots === 'ALLOWED';
  const robotsUnknown = d.robots === 'UNKNOWN';
  const serverOk = status >= 200 && status < 300;
  const rateLimited = status === 429 || status === 503;

  // A page that is served but far smaller than the browser version is a partial block.
  const thin = serverOk && controlLength > 0 && length < controlLength * 0.5;

  let verdict, explanation;
  if (rateLimited) {
    verdict = 'RATE_LIMITED';
    explanation = `The server answered ${status}, which means rate limiting, not a bot decision. This audit sends one request per bot, so a strict limiter can trip on the audit itself.` + (d.__retryAfter ? ` The server asks you to wait ${d.__retryAfter} seconds, so leave at least that long before running it again.` : ' Wait several minutes before running it again, because limiters usually keep blocking after a trip.') + ' Raise secondsBetweenRequests and retry before drawing any conclusions.';
  } else if (robotsUnknown) {
    verdict = 'UNKNOWN';
    explanation = `${d.robotsDetail}. The server answered ${status} for this bot, but without robots.txt there is nothing to compare it against.`;
  } else if (!robotsAllowed && !serverOk) {
    verdict = 'BLOCKED';
    explanation = `Blocked on purpose. robots.txt says ${d.robotsDetail}, and the server answers ${status}.`;
  } else if (!robotsAllowed) {
    verdict = 'BLOCKED';
    explanation = `Blocked by robots.txt: ${d.robotsDetail}. Well-behaved bots will not read this page.`;
  } else if (!serverOk) {
    verdict = 'CONTRADICTION';
    explanation = `robots.txt allows this bot, but the server answers ${status}. A firewall, WAF or bot rule is blocking it even though you said it could come in.`;
  } else if (thin) {
    verdict = 'PARTIAL';
    explanation = `The bot gets a page, but it is much smaller than what a browser receives (${length} vs ${controlLength} characters). It may be getting a challenge page or a stripped version.`;
  } else {
    verdict = 'ALLOWED';
    explanation = `Full access. robots.txt: ${d.robotsDetail}. The server answers ${status} with a page of normal size.`;
  }

  results.push({
    bot: d.bot,
    purpose: d.purpose,
    verdict,
    robots: d.robots,
    httpStatus: status,
    bytesVsBrowser: controlLength > 0 ? Math.round((length / controlLength) * 100) + '%' : 'n/a',
    explanation,
  });
}

const order = { CONTRADICTION: 0, PARTIAL: 1, RATE_LIMITED: 2, UNKNOWN: 3, BLOCKED: 4, ALLOWED: 5 };
results.sort((a, b) => order[a.verdict] - order[b.verdict] || a.bot.localeCompare(b.bot));

const counts = results.reduce((acc, r) => {
  acc[r.verdict] = (acc[r.verdict] || 0) + 1;
  return acc;
}, {});

const summary = [
  `Allowed: ${counts.ALLOWED || 0}`,
  `Blocked: ${counts.BLOCKED || 0}`,
  `Partial: ${counts.PARTIAL || 0}`,
  `Contradictions: ${counts.CONTRADICTION || 0}`,
  ...(counts.RATE_LIMITED ? [`Rate limited: ${counts.RATE_LIMITED}`] : []),
  ...(counts.UNKNOWN ? [`Unknown: ${counts.UNKNOWN}`] : []),
].join(' | ');

const warning = counts.RATE_LIMITED
  ? 'Warning: some requests were rate limited, so those rows say nothing about bot access. Increase the delay between requests and run the audit again.'
  : '';

return results.map((r, i) => ({
  json: i === 0
    ? { ...r, summary, warning, testUrl: $('Set Audit Parameters').first().json.testUrl, controlStatus }
    : r,
}));
